begin;
create table if not exists public.mme_procurement_requisitions(requisition_id uuid primary key default gen_random_uuid(),requisition_number text not null unique,requesting_location_id uuid references public.mme_inventory_locations(location_id),department text not null,justification text not null,required_by date,budget_code text,estimated_total numeric(16,2) not null default 0 check(estimated_total>=0),currency_code char(3) not null default 'USD',requisition_status text not null default 'draft' check(requisition_status in('draft','submitted','approved','rejected','converted','cancelled')),requested_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now());
create table if not exists public.mme_procurement_requisition_lines(requisition_line_id uuid primary key default gen_random_uuid(),requisition_id uuid not null references public.mme_procurement_requisitions(requisition_id) on delete restrict,inventory_item_id uuid references public.mme_inventory_items(inventory_item_id),description text not null,quantity numeric(14,3) not null check(quantity>0),estimated_unit_cost numeric(16,2) not null check(estimated_unit_cost>=0),created_at timestamptz not null default now());
create table if not exists public.mme_procurement_approvals(approval_id uuid primary key default gen_random_uuid(),subject_type text not null check(subject_type in('requisition','purchase_order','vendor','contract')),subject_id uuid not null,approval_level integer not null default 1 check(approval_level>0),decision text not null check(decision in('pending','approved','rejected')),approver_auth_user_id uuid not null,decision_note text,decided_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_vendor_contracts(contract_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_financial_vendors(vendor_id),contract_number text not null unique,title text not null,start_date date not null,end_date date,contract_status text not null default 'draft' check(contract_status in('draft','under_review','approved','active','expired','terminated')),currency_code char(3) not null default 'USD',contract_value numeric(16,2) check(contract_value is null or contract_value>=0),document_path text,created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),check(end_date is null or end_date>=start_date));
create table if not exists public.mme_vendor_quotes(quote_id uuid primary key default gen_random_uuid(),requisition_id uuid not null references public.mme_procurement_requisitions(requisition_id),vendor_id uuid not null references public.mme_financial_vendors(vendor_id),quote_reference text not null,quoted_total numeric(16,2) not null check(quoted_total>=0),currency_code char(3) not null default 'USD',valid_until date,lead_time_days integer check(lead_time_days is null or lead_time_days>=0),quote_status text not null default 'received' check(quote_status in('received','shortlisted','selected','rejected','expired')),notes text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(vendor_id,quote_reference));
create table if not exists public.mme_purchase_order_lines(po_line_id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.mme_purchase_orders(purchase_order_id) on delete restrict,inventory_item_id uuid references public.mme_inventory_items(inventory_item_id),description text not null,quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(16,2) not null check(unit_cost>=0),received_quantity numeric(14,3) not null default 0 check(received_quantity>=0 and received_quantity<=quantity),created_at timestamptz not null default now());
create table if not exists public.mme_procurement_receiving_matches(receiving_match_id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.mme_purchase_orders(purchase_order_id),po_line_id uuid not null references public.mme_purchase_order_lines(po_line_id),inventory_receipt_id uuid references public.mme_inventory_receipts(receipt_id),matched_quantity numeric(14,3) not null check(matched_quantity>0),matched_by_auth_user_id uuid not null,match_status text not null default 'matched' check(match_status in('matched','exception','reversed')),created_at timestamptz not null default now());
create table if not exists public.mme_vendor_returns(vendor_return_id uuid primary key default gen_random_uuid(),return_number text not null unique,vendor_id uuid not null references public.mme_financial_vendors(vendor_id),purchase_order_id uuid references public.mme_purchase_orders(purchase_order_id),return_reason text not null,return_status text not null default 'draft' check(return_status in('draft','approved','shipped','credited','closed','rejected')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now());
create table if not exists public.mme_vendor_return_lines(return_line_id uuid primary key default gen_random_uuid(),vendor_return_id uuid not null references public.mme_vendor_returns(vendor_return_id),inventory_item_id uuid references public.mme_inventory_items(inventory_item_id),description text not null,quantity numeric(14,3) not null check(quantity>0),unit_cost numeric(16,2) check(unit_cost is null or unit_cost>=0));
create table if not exists public.mme_vendor_performance_reviews(review_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_financial_vendors(vendor_id),review_period_start date not null,review_period_end date not null,on_time_delivery_pct numeric(5,2) check(on_time_delivery_pct between 0 and 100),quality_score numeric(5,2) check(quality_score between 0 and 100),price_score numeric(5,2) check(price_score between 0 and 100),service_score numeric(5,2) check(service_score between 0 and 100),review_notes text,reviewed_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(review_period_end>=review_period_start));
create table if not exists public.mme_procurement_audit_events(event_id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,action text not null,actor_auth_user_id uuid not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.mme_decide_procurement_approval(p_approval uuid,p_decision text,p_note text,p_actor uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare a public.mme_procurement_approvals%rowtype; created uuid;
begin
 if p_decision not in('approved','rejected') then raise exception 'invalid_approval_decision'; end if;
 select * into a from public.mme_procurement_approvals where approval_id=p_approval for update;
 if not found then raise exception 'approval_not_found'; end if;
 if a.decision<>'pending' then raise exception 'approval_already_decided'; end if;
 if a.approver_auth_user_id<>p_actor then raise exception 'assigned_approver_required'; end if;
 update public.mme_procurement_approvals set decision=p_decision,decision_note=p_note,decided_at=now() where approval_id=p_approval;
 if a.subject_type='requisition' then update public.mme_procurement_requisitions set requisition_status=case when p_decision='approved' then 'approved' else 'rejected' end,approved_by_auth_user_id=p_actor where requisition_id=a.subject_id and requisition_status='submitted';
 elsif a.subject_type='purchase_order' then update public.mme_purchase_orders set po_status=case when p_decision='approved' then 'approved' else 'cancelled' end,approved_by_auth_user_id=p_actor where purchase_order_id=a.subject_id and po_status='submitted';
 elsif a.subject_type='vendor' then update public.mme_financial_vendors set vendor_status=case when p_decision='approved' then 'active' else 'blocked' end where vendor_id=a.subject_id;
 elsif a.subject_type='contract' then update public.mme_vendor_contracts set contract_status=case when p_decision='approved' then 'approved' else 'terminated' end,approved_by_auth_user_id=p_actor where contract_id=a.subject_id and contract_status='under_review';
 end if;
 insert into public.mme_procurement_audit_events(entity_type,entity_id,action,actor_auth_user_id,metadata) values(a.subject_type,a.subject_id,'approval_'||p_decision,p_actor,jsonb_build_object('approval_id',p_approval,'note',p_note));
 return jsonb_build_object('approval_id',p_approval,'decision',p_decision);
end;$$;
revoke all on function public.mme_decide_procurement_approval(uuid,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_decide_procurement_approval(uuid,text,text,uuid) to service_role;
do $$declare t text;begin foreach t in array array['mme_procurement_requisitions','mme_procurement_requisition_lines','mme_procurement_approvals','mme_vendor_contracts','mme_vendor_quotes','mme_purchase_order_lines','mme_procurement_receiving_matches','mme_vendor_returns','mme_vendor_return_lines','mme_vendor_performance_reviews','mme_procurement_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;